"""OpenTelemetry span exporter for PRISMtrace.

This is a client-side shim: it converts OpenTelemetry spans into PRISMtrace's
native ``/api/spans/ingest`` payload, in-process, without an OTLP exporter.

It is usually NOT what you want. PRISM serves OTLP over HTTP at
``POST /api/otlp/v1/traces`` (ADR-0141, protobuf as well as JSON since
ADR-0148), so an already-instrumented service can point its existing exporter
straight at PRISM in any language; only gRPC is not served. Reach for this shim
only when you are already on this SDK and do not want to run an exporter.

Three things were wrong with this module before, and all three were reachable
from the example published in the SDK README:

  * it authenticated with ``Authorization: Bearer``, but the ingest route reads
    only ``X-PRISMtrace-Key``. Depending on ``INGEST_AUTH_MODE`` that is either
    a 401 or an ingest with no credential checked at all;
  * it read ``prismtrace.*`` attributes and nothing else, so anyone instrumented
    with a standard GenAI library got no model, no tokens and no text;
  * it sent no ``session_id``, so every exported trace arrived ungrouped.

Attributes are now read from the OpenTelemetry GenAI semantic conventions as
well, with the deprecated spellings kept as fallbacks because real-world
instrumentation still emits them. A ``prismtrace.*`` attribute always wins,
since setting one is an explicit statement about this backend.
"""
from __future__ import annotations


import json
from typing import Any, Optional, Sequence

import httpx
from ._config import DEFAULT_HOST, resolve_host
from ._session import current_session

try:
    from opentelemetry.sdk.trace import ReadableSpan
    from opentelemetry.sdk.trace.export import SpanExporter, SpanExportResult
    from opentelemetry.sdk.trace import SpanProcessor, TracerProvider
    from opentelemetry.sdk.trace.export import BatchSpanProcessor
    from opentelemetry import trace

    _HAS_OTEL = True
except ImportError:
    _HAS_OTEL = False
    SpanProcessor = object  # type: ignore[assignment,misc]


# Where PRISMtrace stores the session it resolved, so the exporter can read it
# back off the span on whatever thread the batch processor exports from.
_SESSION_ATTR = "prismtrace.session_id"

# GenAI semantic-convention keys, current name first and the superseded
# spelling second. gen_ai.system, gen_ai.usage.prompt_tokens,
# gen_ai.usage.completion_tokens, gen_ai.prompt and gen_ai.completion are all
# deprecated, but instrumentation in the wild still emits them.
_MODEL_KEYS = ("gen_ai.response.model", "gen_ai.request.model", "llm.model_name")
_INPUT_TOKEN_KEYS = ("gen_ai.usage.input_tokens", "gen_ai.usage.prompt_tokens")
_OUTPUT_TOKEN_KEYS = ("gen_ai.usage.output_tokens", "gen_ai.usage.completion_tokens")
_INPUT_TEXT_KEYS = ("gen_ai.input.messages", "gen_ai.prompt")
_OUTPUT_TEXT_KEYS = ("gen_ai.output.messages", "gen_ai.completion")

# Prefixes under which instrumentation explodes a chat history across keys.
# OTLP attributes are flat, so a message list becomes gen_ai.prompt.0.role /
# gen_ai.prompt.0.content (openllmetry) or llm.input_messages.0.message.role
# (OpenInference). Reading only the flat spellings above finds neither, which
# is every prompt and completion from the two most widely deployed GenAI
# instrumentations.
_INDEXED_INPUT_PREFIXES = ("gen_ai.prompt", "llm.input_messages")
_INDEXED_OUTPUT_PREFIXES = ("gen_ai.completion", "llm.output_messages")
_SESSION_KEYS = ("gen_ai.conversation.id", "session.id")
_PROVIDER_KEYS = ("gen_ai.provider.name", "gen_ai.system")

# gen_ai.operation.name to PRISMtrace span_type. Anything unrecognised stays a
# chain, which is what this exporter defaulted to for every span before.
_OPERATION_SPAN_TYPES = {
    "chat": "llm",
    "text_completion": "llm",
    "generate_content": "llm",
    "embeddings": "retrieval",
    "execute_tool": "tool",
    "invoke_agent": "agent",
    "create_agent": "agent",
}


def _first(attrs: dict, keys: Sequence[str]) -> Any:
    for key in keys:
        value = attrs.get(key)
        if value is not None:
            return value
    return None


def _indexed_messages(attrs: dict, prefix: str) -> Optional[str]:
    """Reassemble a flattened message list into one block of text.

    Kept deliberately identical to ``_indexed_messages`` in the server-side
    receiver (``backend/app/services/otlp_mapping.py``). The same span must not
    read differently depending on whether it arrived through this exporter or
    through OTLP, so any change here belongs in both.

    Both shapes are handled by taking the leaf segment of whatever follows the
    index, so OpenInference's extra ``message.`` level needs no second path.
    Ordering is by integer index, not dict order: 10 must not sort before 2.
    """
    rows: dict = {}
    needle = prefix + "."

    for key, value in attrs.items():
        if not key.startswith(needle):
            continue
        remainder = key[len(needle):]
        index_part, _, tail = remainder.partition(".")
        if not index_part.isdigit():
            continue
        leaf = tail.rsplit(".", 1)[-1]
        if leaf not in ("content", "role"):
            continue
        text = _as_text(value)
        if text is None:
            continue
        rows.setdefault(int(index_part), {})[leaf] = text

    if not rows:
        return None

    parts = []
    for index in sorted(rows):
        content = rows[index].get("content")
        if not content:
            continue
        role = rows[index].get("role")
        parts.append(f"{role}: {content}" if role else content)

    return "\n".join(parts) or None


def _message_text(attrs: dict, flat_keys, indexed_prefixes) -> Optional[str]:
    """Flat spelling first, then the indexed one. Explicit beats reassembled."""
    flat = _as_text(_first(attrs, flat_keys))
    if flat:
        return flat
    for prefix in indexed_prefixes:
        joined = _indexed_messages(attrs, prefix)
        if joined:
            return joined[:10000]
    return None


def _as_text(value: Any, limit: int = 10000) -> Optional[str]:
    """GenAI message attributes are structured; span text fields are strings."""
    if value is None:
        return None
    if isinstance(value, str):
        return value[:limit]
    try:
        return json.dumps(value, default=str)[:limit]
    except Exception:
        return str(value)[:limit]


def _as_int(value: Any) -> Optional[int]:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


class PRISMtraceSpanExporter:
    """Exports OpenTelemetry spans to PRISMtrace /api/spans/ingest."""

    def __init__(
        self,
        api_key: str,
        project_id: str,
        endpoint: Optional[str] = None,
        session_id: Optional[str] = None,
        timeout: int = 10,
    ):
        self.api_key = api_key
        self.project_id = project_id
        self.endpoint = resolve_host(endpoint)
        # Seconds per POST; the SDK fails open, so this bounds silent loss
        # against a slow backend (KAN-47). Same argument the voice tracer takes.
        self.timeout = timeout
        # An explicit session pins every exported trace to one id. Left unset,
        # the session is taken from the span, which is where the ambient one was
        # stamped at span start. It cannot be read here: a BatchSpanProcessor
        # exports on its own thread, which no contextvar reaches.
        self.session_id = (session_id or "").strip() or None
        self._closed = False
        self._client = httpx.Client(
            headers={
                # Not "Authorization: Bearer". POST /api/spans/ingest reads this
                # header and only this header.
                "X-PRISMtrace-Key": api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )

    def export(self, spans: "Sequence[ReadableSpan]") -> "SpanExportResult":
        if not spans:
            if _HAS_OTEL:
                return SpanExportResult.SUCCESS
            return None

        # Group spans by trace ID
        by_trace: dict = {}
        sessions: dict = {}
        for span in spans:
            ctx = span.get_span_context()
            trace_id = format(ctx.trace_id, "032x")
            if trace_id not in by_trace:
                by_trace[trace_id] = []

            parent_span_id = None
            if span.parent and span.parent.span_id:
                parent_span_id = format(span.parent.span_id, "016x")

            attrs = dict(span.attributes or {})
            span_type = attrs.pop("prismtrace.span_type", None)
            if not span_type:
                operation = attrs.get("gen_ai.operation.name")
                span_type = _OPERATION_SPAN_TYPES.get(str(operation), "chain")

            session_id = (
                self.session_id
                or attrs.get(_SESSION_ATTR)
                or _first(attrs, _SESSION_KEYS)
            )
            if session_id and trace_id not in sessions:
                sessions[trace_id] = str(session_id)

            start_ns = span.start_time or 0
            end_ns = span.end_time or start_ns
            duration_ms = (end_ns - start_ns) / 1e6

            from datetime import datetime, timezone

            start_time = datetime.fromtimestamp(start_ns / 1e9, tz=timezone.utc).isoformat()
            end_time = datetime.fromtimestamp(end_ns / 1e9, tz=timezone.utc).isoformat()

            metadata = {
                k: v
                for k, v in attrs.items()
                if not k.startswith("prismtrace.")
            }
            provider = _first(attrs, _PROVIDER_KEYS)
            if provider and "provider" not in metadata:
                metadata["provider"] = provider

            by_trace[trace_id].append({
                "span_id": format(ctx.span_id, "016x"),
                "parent_span_id": parent_span_id,
                "name": span.name,
                "span_type": span_type,
                "input_text": _as_text(attrs.get("prismtrace.input"))
                or _message_text(attrs, _INPUT_TEXT_KEYS, _INDEXED_INPUT_PREFIXES),
                "output_text": _as_text(attrs.get("prismtrace.output"))
                or _message_text(attrs, _OUTPUT_TEXT_KEYS, _INDEXED_OUTPUT_PREFIXES),
                "metadata": metadata,
                "start_time": start_time,
                "end_time": end_time,
                "duration_ms": duration_ms,
                "status": "error" if span.status and span.status.is_ok is False else "ok",
                "error_message": attrs.get("prismtrace.error"),
                "token_count_input": _as_int(
                    attrs.get("prismtrace.token_count_input")
                    if attrs.get("prismtrace.token_count_input") is not None
                    else _first(attrs, _INPUT_TOKEN_KEYS)
                ),
                "token_count_output": _as_int(
                    attrs.get("prismtrace.token_count_output")
                    if attrs.get("prismtrace.token_count_output") is not None
                    else _first(attrs, _OUTPUT_TOKEN_KEYS)
                ),
                "cost_usd": attrs.get("prismtrace.cost_usd"),
                "model": attrs.get("prismtrace.model") or _first(attrs, _MODEL_KEYS),
            })

        failed = False
        for trace_id, span_list in by_trace.items():
            payload = {
                "trace_id": trace_id,
                "project_id": self.project_id,
                "spans": span_list,
            }
            session_id = sessions.get(trace_id)
            if session_id:
                payload["session_id"] = session_id
            try:
                self._client.post(
                    f"{self.endpoint}/api/spans/ingest",
                    json=payload,
                )
            except Exception as e:
                print(f"PRISMtrace export error: {e}")
                failed = True

        if _HAS_OTEL:
            return SpanExportResult.FAILURE if failed else SpanExportResult.SUCCESS
        return None

    def shutdown(self) -> None:
        self.close()

    def close(self) -> None:
        """Release the HTTP connection pool. Idempotent."""
        if self._closed:
            return
        self._closed = True
        try:
            self._client.close()
        except Exception:
            pass

    def __enter__(self) -> "PRISMtraceSpanExporter":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False

    def force_flush(self, timeout_millis: int = 30000) -> bool:
        return True


class _AmbientSessionProcessor(SpanProcessor):  # type: ignore[misc,valid-type]
    """Stamps the ambient session onto each span as it starts.

    The session has to be read here rather than in the exporter: a
    BatchSpanProcessor exports from its own thread, and a contextvar does not
    follow a thread. An explicit attribute already on the span is left alone.
    """

    def on_start(self, span: Any, parent_context: Any = None) -> None:
        session_id = current_session()
        if not session_id:
            return
        try:
            if (span.attributes or {}).get(_SESSION_ATTR):
                return
            span.set_attribute(_SESSION_ATTR, session_id)
        except Exception:
            # Tracing must never break the caller's request.
            pass

    def on_end(self, span: Any) -> None:
        return

    def shutdown(self) -> None:
        return

    def force_flush(self, timeout_millis: int = 30000) -> bool:
        return True


class PRISMtraceInstrumentor:
    """Sets up OpenTelemetry tracing with PRISMtrace as the span exporter."""

    def __init__(self):
        if not _HAS_OTEL:
            raise ImportError(
                "opentelemetry-sdk is required. Install with: "
                "pip install opentelemetry-sdk opentelemetry-api"
            )
        self._provider: Optional["TracerProvider"] = None
        self._exporter: Optional[PRISMtraceSpanExporter] = None

    def instrument(
        self,
        api_key: str,
        project_id: str,
        endpoint: Optional[str] = None,
        session_id: Optional[str] = None,
        timeout: int = 10,
    ) -> None:
        exporter = PRISMtraceSpanExporter(
            api_key=api_key,
            project_id=project_id,
            endpoint=endpoint,
            session_id=session_id,
            timeout=timeout,
        )
        self._exporter = exporter
        self._provider = TracerProvider()
        # Order matters: the session has to be stamped on start, before the
        # batch processor hands the span to an exporter thread.
        self._provider.add_span_processor(_AmbientSessionProcessor())
        self._provider.add_span_processor(BatchSpanProcessor(exporter))
        trace.set_tracer_provider(self._provider)

    def get_tracer(self, name: str = "prismtrace") -> "trace.Tracer":
        if not self._provider:
            raise RuntimeError("Call instrument() before get_tracer()")
        return trace.get_tracer(name)

    def shutdown(self) -> None:
        """Flush pending spans and release the exporter's connection pool."""
        if self._provider is not None:
            try:
                self._provider.shutdown()
            except Exception:
                pass
        if self._exporter is not None:
            self._exporter.close()

    def __enter__(self) -> "PRISMtraceInstrumentor":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.shutdown()
        return False
